import 'package:flutter/foundation.dart';
import 'package:flutter/material.dart';
import 'package:firebase_core/firebase_core.dart';
import 'package:firebase_app_check/firebase_app_check.dart';
import 'firebase_options.dart';
import 'chat_screen.dart';

void main() async {
  WidgetsFlutterBinding.ensureInitialized();
  // firebase_options.dart is generated by `flutterfire configure` — it
  // won't exist (and this import will fail) until you've run that command
  // against your own Firebase project. See the README.md in this repo.
  await Firebase.initializeApp(
    options: DefaultFirebaseOptions.currentPlatform,
  );
  // Activate App Check:
  // - Local runs (`kDebugMode`): uses WebDebugProvider (registers a debug token in console).
  // - Hosted web app (`flutter build web`): uses Google Cloud Fraud Defense
  //   (`ReCaptchaEnterpriseProvider('YOUR_FRAUD_DEFENSE_SITE_KEY')`).
  try {
    await FirebaseAppCheck.instance.activate(
      providerWeb: kDebugMode
          ? WebDebugProvider()
          : ReCaptchaEnterpriseProvider('YOUR_FRAUD_DEFENSE_SITE_KEY'),
      providerApple: const AppleDebugProvider(),
      providerAndroid: const AndroidDebugProvider(),
    );
  } catch (e) {
    debugPrint('App Check activate error: $e');
  }
  runApp(const AskMyDataApp());
}

class AskMyDataApp extends StatelessWidget {
  const AskMyDataApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: 'Ask My Data',
      theme: ThemeData(
        colorSchemeSeed: Colors.deepPurple,
        useMaterial3: true,
      ),
      home: const ChatScreen(),
    );
  }
}
